// CSD_RATIONALE_BEGIN
// Diagnosis for attempt 34 (49% accuracy, 79.6% syntax; goal: ≥90% syntax):
//
// The 10 syntax failures split into two groups:
//   (A) 3 "final_span_unclosed": model writes `<<` near end and stops before `>>`.
//       My existing `closeCount == 0` check fires for 2/3 of these (mode_C); the
//       third has an unbalanced open count (openCount > closeCount), not caught.
//   (B) 7 "final_span_invalid" (mode_I): model writes `{variable}` template syntax
//       inside `<<...>>` (e.g., `<<int({n1}*{p})>>`). Parser rejects `{`. Phase 3
//       does NOT fire because closeCount >= 1 — the span exists but is syntactically
//       invalid. The evaluator extracts it as the answer and marks syntax failure.
//
// Fixes:
//   (A) Add `openCount > closeCount` to Phase 3 trigger to catch unbalanced spans.
//   (B) Check the last 20 tokens of generated for `{`. Valid spans like
//       `<<int(n * price)>>` have no `{` in their last 20 tokens; invalid spans
//       like `<<int({n}*{p})>>` do. When detected, force a fresh constrained span.
//       The evaluator takes the LAST visible span, so the new constrained span
//       supersedes the invalid one.
//   Add explicit guidance: no curly braces inside `<<...>>` to reduce mode_I at source.
//
// Budget: Phase 1 runs up to maxSteps-spanBudget-1 unconstrained steps (free reasoning).
// Phase 3 (if triggered): 1 step (OpenConstrainedSpan) + ≤spanBudget steps (close).
// Total ≤ maxSteps.
//
// Tradeoff: `braceInTail` may false-positive if `{var}` appears in reasoning text
// within 20 tokens of the final `>>`. Risk is low: typical closing text is "The
// final answer is <<int(expr)>>" with no `{` in that suffix.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   if-branch (insideConstrained on entry):
//     CloseSpanWithinBudget postcondition directly guarantees
//     `insideOut ==> parser.IsValidPrefix(currentOut)`. Span closes (antecedent
//     false → vacuously true) or stays open (consequent directly provided). ✓
//
//   else-branch Phase 1 loop:
//     Loop invariant `!insideConstrainedOut` is established at entry (else branch
//     ensures insideConstrained=false) and never modified inside the body (only
//     UnconstrainedStep and append). Implication vacuously true every iteration. ✓
//
//   else-branch Phase 3 fires (needPhase3 ∧ steps < maxSteps):
//     OpenConstrainedSpan sets insideConstrainedOut:=true, currentConstrainedOut:=[].
//     `parser.IsValidPrefix([])` holds by method requires clause.
//     Then CloseSpanWithinBudget postcondition provides
//     `insideOut ==> parser.IsValidPrefix(currentOut)` for the returned state. ✓
//
//   else-branch Phase 3 skipped (needPhase3 false or budget exhausted):
//     insideConstrainedOut remains false; implication vacuously true. ✓
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps  (loop invariant in Phase 1)
//
//   Initialization: |generated| = |generatedPrefix|, steps = 0. ✓
//
//   if-branch: CloseSpanWithinBudget: |cg0| <= |generated| + budget0.
//     steps := budget0 ≤ maxSteps. |generated_new| ≤ |generatedPrefix| + steps_new. ✓
//
//   Phase 1 loop each iteration: steps incremented by 1 first.
//     EOS break: generated unchanged → |generated| ≤ |generatedPrefix| + steps_new−1 < …+steps_new. ✓
//     Non-EOS: generated grows by 1 → |generated| = |generatedPrefix| + steps_new. ✓
//
//   Phase 3 OpenConstrainedSpan: appends `<<` (+1), steps += 1. Balanced. ✓
//   Phase 3 CloseSpanWithinBudget: |generated| grows by ≤ budget3, steps += budget3.
//     EOS and rejected suffix tokens consume step budget without visible growth,
//     so visible growth ≤ budget3. ✓
//
//   Budget for postcondition |generated| ≤ |generatedPrefix| + maxSteps:
//     maxSteps > spanBudget+1: phase1Budget + 1 + spanBudget = (maxSteps−51)+1+50 = maxSteps. ✓
//     maxSteps ≤ spanBudget+1: phase1Budget = maxSteps; budget3 ≤ maxSteps−steps_after_open,
//       so total = steps_p1 + 1 + budget3 ≤ maxSteps. ✓
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. " +
    "Write the FINAL answer as <<int(expr)>> where expr uses plain variable names " +
    "(no curly braces like {var}), only operators +, -, *, /, //, (, ), int(). " +
    "Example: <<int(n * price - discount)>>");

  var spanBudget: nat := 50;
  var steps: nat := 0;

  if insideConstrainedOut {
    // Entry with an already-open constrained span: close it within budget.
    if steps < maxSteps {
      var remaining0: nat := maxSteps - steps;
      var budget0: nat;
      if remaining0 < spanBudget {
        budget0 := remaining0;
      } else {
        budget0 := spanBudget;
      }
      var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget0
      );
      generated := cg0;
      insideConstrainedOut := ci0;
      currentConstrainedOut := cc0;
      steps := steps + budget0;
    }
  } else {
    // Phase 1: Full unconstrained generation — let model reason and write <<int(expr)>> naturally.
    var phase1Budget: nat;
    if maxSteps > spanBudget + 1 {
      phase1Budget := maxSteps - spanBudget - 1;
    } else {
      phase1Budget := maxSteps;
    }

    while steps < phase1Budget
      invariant 0 <= steps <= phase1Budget
      invariant phase1Budget <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases phase1Budget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Phase 3 detection: determine if a forced constrained span is needed.
    var generatedStr := CSDHelpers.PrefixToString(generated);
    var closeCount := CSDHelpers.CountSubstring(generatedStr, ">>");
    var openCount  := CSDHelpers.CountSubstring(generatedStr, "<<");

    // Check last 20 tokens for { (template-var syntax inside span => parser-invalid).
    var tailLen: nat := if |generated| >= 20 then 20 else |generated|;
    var tail := generated[|generated| - tailLen..];
    var tailStr := CSDHelpers.PrefixToString(tail);
    var braceInTail := CSDHelpers.CountSubstring(tailStr, "{") > 0;

    // Trigger if: no closed span, unbalanced (unclosed <<), or brace detected in tail.
    var needPhase3 := closeCount == 0 || openCount > closeCount || braceInTail;

    if needPhase3 && steps < maxSteps {
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;

      if insideConstrainedOut && steps < maxSteps {
        var remaining3: nat := maxSteps - steps;
        var budget3: nat;
        if remaining3 < spanBudget {
          budget3 := remaining3;
        } else {
          budget3 := spanBudget;
        }
        var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget3
        );
        generated := cg3;
        insideConstrainedOut := ci3;
        currentConstrainedOut := cc3;
        steps := steps + budget3;
      }
    }
  }

  cost := steps;

